def _bootstrap_project_files():
    """Ensure `futures/` package and required prompt/config files exist and are synced to v6.0.2."""
    app_root = Path(__file__).resolve().parent
    if str(app_root) not in sys.path:
        sys.path.insert(0, str(app_root))

    marker = app_root / "futures" / ".v602_synced"
    required_rel = (
        "futures/__init__.py",
        "futures/groq_rotation.py",
        "futures/spot_market.py",
        "futures/bybit_market.py",
        "futures/provider_router.py",
        "futures/market_scanner.py",
        "futures/security.py",
        "futures/st_compat.py",
        "futures/strategy.py",
        "futures/paper.py",
        "futures/telegram.py",
        "config/scanner.json",
        "STRATEGY_RULES.txt",
    )
    if marker.exists() and all((app_root / rel).exists() for rel in required_rel):
        return app_root

    target_root = app_root
    try:
        (target_root / "futures").mkdir(parents=True, exist_ok=True)
        probe = target_root / "futures" / ".write_probe"
        probe.write_text("ok", encoding="utf-8")
        probe.unlink(missing_ok=True)
    except OSError:
        target_root = Path(tempfile.gettempdir()) / "coinagentx_runtime_v602"
        target_root.mkdir(parents=True, exist_ok=True)
        if str(target_root) not in sys.path:
            sys.path.insert(0, str(target_root))

    raw_zip = base64.b64decode(_EMBEDDED_BUNDLE_B64)
    with zipfile.ZipFile(io.BytesIO(raw_zip), "r") as zf:
        for member in zf.namelist():
            dest = target_root / member
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_bytes(zf.read(member))
    return target_root


_ACTIVE_ROOT = _bootstrap_project_files()

